注意：3.7+ 版本采用键值对格式配置，旧版是 Erlang 语法的 rabbitmq.config，部署时注意区分，别抄错了格式。


五、Spring Boot 集成：核心代码全落地
这才是大部分同学实际工作中要用到的。先上依赖和配置，再逐个拆解。
5.1 Maven 依赖
<dependency>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-amqp</artifactId>
</dependency>

5.2 application.yml 配置
spring:
  rabbitmq:
    host: 192.168.1.100
    port: 5672
    username: order_admin
    password: YourStrongPassword
    virtual-host: /order_vhost
    # 开启发送端确认（消息到达 Exchange 后有回调）
    publisher-confirm-type: correlated
    # 开启发送端回退（路由到 Queue 失败可感知）
    publisher-returns: true
    # 消费端配置
    listener:
      simple:
        acknowledge-mode: manual   # 手动 ACK，保证消费可靠性
        prefetch: 10               # 每次预取 10 条，配合限流防打爆

5.3 队列与交换机声明（绑定死信队列）
这一步是架构设计的关键——在声明队列的时候就绑定死信交换机，后续消费失败的消息会自动流转到死信队列，不会无限重试阻塞主队列。
@Configuration
public class RabbitOrderConfig {

    // 订单交换机
    @Bean
    public DirectExchange orderExchange() {
        return new DirectExchange("order.exchange", true, false);
    }

    // 订单队列 —— 注意这里绑定了死信交换机
    @Bean
    public Queue orderQueue() {
        Map<String, Object> args = new HashMap<>();
        args.put("x-dead-letter-exchange", "order.dlx.exchange");     // 死信交换机
        args.put("x-dead-letter-routing-key", "order.dlx.routingKey"); // 死信路由 key
        args.put("x-message-ttl", 600000);                             // 消息 TTL 10 分钟
        return new Queue("order.queue", true, false, false, args);
    }

    // 绑定关系
    @Bean
    public Binding orderBinding() {
        return BindingBuilder.bind(orderQueue()).to(orderExchange()).with("order.create");
    }

    // ===== 死信交换机 & 死信队列 =====
    @Bean
    public DirectExchange orderDlxExchange() {
        return new DirectExchange("order.dlx.exchange", true, false);
    }

    @Bean
    public Queue orderDlxQueue() {
        return new Queue("order.dlx.queue", true);
    }

    @Bean
    public Binding orderDlxBinding() {
        return BindingBuilder.bind(orderDlxQueue()).to(orderDlxExchange()).with("order.dlx.routingKey");
    }
}

5.4 生产者：消息落库 + Confirm 回调 + 失败补偿
这是保证消息可靠投递的核心设计：消息先落库，发送成功后更新状态，失败的由定时任务补偿重发。
@Service
public class OrderMessageSender {

    @Autowired
    private RabbitTemplate rabbitTemplate;

    @Autowired
    private MsgLogRepository msgLogRepository;

    /**
     * 发送订单消息
     * 核心思路：先落库 → 再发送 → 回调更新状态 → 失败定时补偿
     */
    public void sendOrderMessage(Order order) {
        // 1. 消息落库，status=0（待确认）
        MsgLog msgLog = new MsgLog();
        msgLog.setMsgId(UUID.randomUUID().toString());
        msgLog.setContent(JSON.toJSONString(order));
        msgLog.setStatus(0);
        msgLogRepository.save(msgLog);

        // 2. 携带 msgId 发送，用于回调匹配
        CorrelationData correlationData = new CorrelationData(msgLog.getMsgId());
        rabbitTemplate.convertAndSend("order.exchange", "order.create", order, correlationData);
    }

    // 统一设置 Confirm 和 Return 回调
    @PostConstruct
    public void initRabbitTemplate() {
        // ConfirmCallback：消息是否到达 Exchange
        rabbitTemplate.setConfirmCallback((correlationData, ack, cause) -> {
            String msgId = correlationData.getId();
            if (ack) {
                msgLogRepository.updateStatus(msgId, 1); // 成功
            } else {
                msgLogRepository.updateStatus(msgId, 2); // 失败，等待补偿
                log.error("消息发送到 Exchange 失败, msgId: {}", msgId);
            }
        });

        // ReturnCallback：消息路由不到 Queue 时触发
        rabbitTemplate.setReturnCallback((message, replyCode, replyText, exchange, routingKey) -> {
            String msgId = message.getMessageProperties().getCorrelationId();
            msgLogRepository.updateStatus(msgId, 2);
            log.error("消息路由失败, msgId: {}, replyText: {}", msgId, replyText);
        });
    }
}

5.5 消费者：手动 ACK + 幂等校验 + 死信兜底
@Component
public class OrderConsumer {

    @Autowired
    private MsgLogRepository msgLogRepository;

    @Autowired
    private BusinessService businessService;

    @RabbitListener(queues = "order.queue")
    public void handleOrder(Message message, Channel channel) throws IOException {
        String msgId = message.getMessageProperties().getCorrelationId();
        Order order = JSON.parseObject(message.getBody(), Order.class);

        try {
            // ① 幂等判断：这条消息是否已经处理过了？
            if (msgLogRepository.isMsgProcessed(msgId)) {
                channel.basicAck(message.getMessageProperties().getDeliveryTag(), false);
                return; // 已处理，直接 ACK 丢弃
            }

            // ② 核心业务逻辑：发短信、加积分、写日志……
            businessService.process(order);

            // ③ 标记已处理 + 手动 ACK
            msgLogRepository.markProcessed(msgId);
            channel.basicAck(message.getMessageProperties().getDeliveryTag(), false);

        } catch (Exception e) {
            log.error("消费异常, msgId: {}", msgId, e);
            // 拒绝
